import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal } from "../src/pricing.ts";

test("calcTotal: no discount under 10 units", () => {
  // 9 units, $27 subtotal
  assert.equal(calcTotal([{ sku: "a", price: 3, qty: 4 }, { sku: "b", price: 3, qty: 5 }]), 27);
});

test("calcTotal: 10% off at 10 or more units", () => {
  // 10 units, $30 subtotal -> $27
  assert.equal(calcTotal([{ sku: "a", price: 3, qty: 4 }, { sku: "b", price: 3, qty: 6 }]), 27);
  // 12 units across items, $40 subtotal -> $36
  assert.equal(calcTotal([{ sku: "a", price: 2, qty: 10 }, { sku: "b", price: 10, qty: 2 }]), 36);
});

